export const anchorSlot = 0; // Upper-left star in both Guda charts.

export function rotateStars(anchor, pivot = anchorSlot) {
  return stars.map(([, group], slot) => ({
    star: (anchor + slot - pivot + stars.length) % stars.length,
    group
  }));
}
